const b = $json.body || $json;
const catalogo = {
  'pareto-psicopedagogas': { titulo: 'Pareto para psicopedagogas', rol: 'psicopedagogas', libro: 'pareto' },
  'habitos-docentes': { titulo: 'Hábitos para docentes', rol: 'docentes', libro: 'habitos' },
};
const slug = String(b.slug || b.sku || '').trim();
const email = String(b.email || '').trim();
const item = catalogo[slug];
if (!item) {
  return [{ json: { ok: false, error: 'slug desconocido', slugs: Object.keys(catalogo), sin_api: true } }];
}
return [{ json: {
  ok: true, sistema: '10-vertice-pdf-upsell', etapa: 'pedido_pdf', sin_api: true,
  orderId: `ORD-${Date.now()}`, slug, email, pdf: item,
  brief_cursor: { slug, titulo: item.titulo, rol: item.rol, libro: item.libro, accion: 'generar_o_entregar_pdf' },
  siguiente: 'oferta_upsell',
  todo: 'SIN API: mock OK. Después: Shopify webhook + pipeline Cursor',
  at: new Date().toISOString()
}}];
